        const RF_LIPD = [[433.05, 434.79], [915, 928], [2400, 2483.5], [5725, 5875]];
        const rfRanges = (s) => String(s || '').split(/[,;+]/).map(x => x.trim().match(/^(\d+(?:\.\d+)?)\s*(?:-|–|to)\s*(\d+(?:\.\d+)?)$/i)).filter(Boolean).map(m => { const a = parseFloat(m[1]), b = parseFloat(m[2]); return [Math.min(a, b), Math.max(a, b)]; }).filter(r => r[1] > r[0]);
        const rfFmt = (r) => r.map(([a, b]) => a + '–' + b + ' MHz').join(' + ');
        // Overlaps: ours vs theirs, and ours vs ours (two of our own video links on the same channel)
        const rfConflicts = (items) => {
          const out = [], L = (items || []).map(i => ({ ...i, r: rfRanges(i.mhz) })).filter(i => i.r.length);
          for (let x = 0; x < L.length; x++) for (let y = x + 1; y < L.length; y++) {
            const a = L[x], b = L[y];
            if (a.side === 'them' && b.side === 'them') continue;
            if (a.side === 'us' && b.side === 'us' && !(a.kind === 'video' && b.kind === 'video') && !(a.kind === 'comms' && b.kind === 'comms')) continue;
            let ov = null, gap = Infinity;
            a.r.forEach(p => b.r.forEach(q => { const lo = Math.max(p[0], q[0]), hi = Math.min(p[1], q[1]); if (hi > lo) ov = ov ? [Math.min(ov[0], lo), Math.max(ov[1], hi)] : [lo, hi]; else gap = Math.min(gap, lo - hi); }));
            if (ov) {
              const wide = (i) => i.r.reduce((m, r) => Math.max(m, r[1] - r[0]), 0) >= 60;
              const hop = (i) => i.kind === 'control';
              const sev = a.kind === 'pyro' || b.kind === 'pyro' ? 'pyro' : (hop(a) && hop(b)) || (wide(a) && wide(b) && (hop(a) || hop(b))) ? 'shared' : 'clash';
              out.push({ a, b, ov, sev });
            } else if (gap < 10) out.push({ a, b, ov: null, gap, sev: 'near' });
          }
          return out;
        };
        const rfConflictText = (c) => c.sev === 'near'
          ? `${c.a.label} and ${c.b.label} are only ${Math.round(c.gap * 10) / 10} MHz apart — keep antennas separated and confirm with a power-up test.`
          : c.sev === 'pyro'
            ? `${c.a.label} shares ${Math.round(c.ov[0])}–${Math.round(c.ov[1])} MHz with ${c.b.label}. Pyro firing is safety-critical: the pyro tech must confirm their system's band/channel, and do a full power-up test with all our transmitters on before arming. Consider moving our link off that band.`
          : c.sev === 'shared'
