        const CREW_FIELD_LABELS = { weatherMeetsLimitations: 'Weather within limitations', weatherDetails: 'Weather details', onsiteValidationInitials: 'On-site validation initials', planningErrors: 'Planning errors', conductedIAW: 'Conducted IAW plan', conductedChanges: 'Changes to the plan', comments: 'Comments', serviceableAtEnd: 'Serviceable at end', defects: 'Defects', crewRP: 'Remote pilot', crewSecondRP: 'Second RP', crewObserver: 'Observer' };
        const crewBlankFlight = (f) => !f || (!String(f.duration == null ? '' : f.duration).trim() && !String(f.batteries || '').trim() && !String(f.label || '').trim() && !f.telemetry
          && !(f.segments || []).some(s => s && (String(s.maxFt == null ? '' : s.maxFt).trim() || String(s.minFt == null ? '' : s.minFt).trim() || String(s.height == null ? '' : s.height).trim())));
        function mergeCrewLog(prev, incoming) {
          const p = prev || {}, out = { ...p }, changes = [];
          const short = (s) => { s = String(s).replace(/\s+/g, ' ').trim(); return s.length > 40 ? s.slice(0, 39) + '…' : s; };
          Object.keys(incoming || {}).forEach(k => {
            if (k === 'rpaLogs') return;
            const v = incoming[k], label = CREW_FIELD_LABELS[k] || k;
            if (typeof v === 'boolean') { if (v && !p[k]) { out[k] = true; changes.push(label + ': ticked'); } return; }
            if (v == null || typeof v === 'object') return;
            const s = String(v).trim(); if (!s) return;
            const cur = p[k] == null ? '' : String(p[k]).trim();
            if (s === cur) return;
            out[k] = v;
            changes.push(cur ? `${label}: "${short(cur)}" → "${short(s)}"` : `${label}: "${short(s)}"`);
          });
          const rl = { ...(p.rpaLogs || {}) };
          const sig = (f) => [String(f.label || '').trim(), String(f.duration == null ? '' : f.duration).trim(), String(f.batteries || '').trim()].join('|');
          let nextId = Date.now();
          Object.entries((incoming && incoming.rpaLogs) || {}).forEach(([rpa, lg]) => {
            const inc = ((lg && lg.flights) || []).filter(f => !crewBlankFlight(f));
            if (!inc.length) return;
            const mine = (rl[rpa] && rl[rpa].flights) || [];
            const kept = mine.filter(f => !crewBlankFlight(f)), have = new Set(kept.map(sig));
            const add = inc.filter(f => !have.has(sig(f))).map(f => ({ ...f, id: nextId++, source: 'crew' }));
            if (!add.length) return;
            rl[rpa] = { ...(rl[rpa] || {}), flights: [...kept, ...add] };
            changes.push(`${rpa}: ${add.length} flight${add.length === 1 ? '' : 's'} added from the crew log`);
          });
          out.rpaLogs = rl;
          return { log: out, changes };
        }

        // --- TAB GUARD: only one tab or window may write the database at a time ---
        // Without this, two open tabs each save their own copy and the last one to save wins.
        const wdTabs = (() => {
          const me = Date.now() + Math.random(), started = Date.now();
          let role = 'pending', ch = null, dirty = false;
          const subs = new Set(), remote = new Set();
          const set = (r) => { if (role === r) return; role = r; wdStore.locked = (r === 'reader'); subs.forEach(f => { try { f(r); } catch (e) {} }); };
          try { ch = new BroadcastChannel('wakingdream_planner'); } catch (e) { ch = null; }
          if (ch) {
            ch.onmessage = (e) => {
              const m = e.data || {};
              if (m.from === me) return;
              if (m.t === 'hello' && role === 'writer') ch.postMessage({ t: 'here', from: me, started });
              else if (m.t === 'here') {
                if (role === 'pending') set('reader');
                else if (role === 'writer' && (m.started < started || (m.started === started && m.from < me))) {
                  // Two tabs both thought they were the writer. The one with unsaved work keeps writing (v5.45).
                  if (dirty) { try { ch.postMessage({ t: 'takeover', from: me }); } catch (e3) {} } else set('reader');
                }
              }
              else if (m.t === 'takeover' && role === 'writer') set('reader');
              else if (m.t === 'saved' && role === 'reader') remote.forEach(f => { try { f(); } catch (e2) {} });
            };
            ch.postMessage({ t: 'hello', from: me, started });
            setTimeout(() => { if (role === 'pending') set('writer'); }, 400);
            wdStore.onSaved = () => { try { ch.postMessage({ t: 'saved', from: me }); } catch (e) {} };
          } else role = 'writer';
          return {
            get role() { return role; },
            subscribe(f) { subs.add(f); return () => subs.delete(f); },
            onRemoteSave(f) { remote.add(f); return () => remote.delete(f); },
            id: me,
            setDirty(b) { dirty = !!b; },
            // v5.45: no reload — the form on screen is kept. Database writes pause until the app re-reads the stored database.
            takeover() { try { ch && ch.postMessage({ t: 'takeover', from: me }); } catch (e) {} if (role !== 'writer') { wdStore.freshPending = true; set('writer'); } },
          };
        })();
        try { navigator.storage && navigator.storage.persist && navigator.storage.persist(); } catch (e) {}

        // --- CROWD HEATMAP RENDERER (geo-anchored brush dabs) ---
        // dabs: [{lat,lng,rM,c,o,e}] — rM radius in metres, c density id, o opacity, e erase
        // project(lat,lng) -> {x,y} container px; mpp = metres per screen pixel at the current zoom
        function drawHeatDabs(ctx, dabs, project, mpp) {
          var COLS = { low:'rgba(34,197,94,', moderate:'rgba(234,179,8,', high:'rgba(249,115,22,', dense:'rgba(239,68,68,', exclusion:'rgba(127,29,29,' };
          for (var i = 0; i < dabs.length; i++) {
            var d = dabs[i];
            var pt = project(d.lat, d.lng);
            var r = Math.max(1, d.rM / mpp(d.lat));
            ctx.beginPath();
            ctx.arc(pt.x, pt.y, r, 0, Math.PI * 2);
            if (d.e) {
              ctx.globalCompositeOperation = 'destination-out';
              ctx.fillStyle = 'rgba(0,0,0,1)';
              ctx.fill();
              ctx.globalCompositeOperation = 'source-over';
            } else {
              var cb = COLS[d.c] || COLS.high, o = d.o;
              var g = ctx.createRadialGradient(pt.x, pt.y, 0, pt.x, pt.y, r);
              g.addColorStop(0, cb + o + ')');
              g.addColorStop(0.2, cb + (o * 0.75) + ')');
              g.addColorStop(0.5, cb + (o * 0.35) + ')');
              g.addColorStop(0.8, cb + (o * 0.10) + ')');
              g.addColorStop(1, cb + '0)');
              ctx.fillStyle = g;
              ctx.fill();
            }
          }
        }
        // Web-Mercator metres per pixel for a Leaflet zoom level
        function heatMpp(zoom) { return function (lat) { return 156543.03392 * Math.cos(lat * Math.PI / 180) / Math.pow(2, zoom); }; }

        // --- OPERATION WINDOW: separate start date+time and end date+time ---
        // End date blank = same day as start (keeps older plans working)
        const opWindow = (ov) => {
          const sd = ov.operationDate || '', ed = ov.operationEndDate || ov.operationDate || '';
          const st = ov.startTime || '', et = ov.endTime || '';
          const s = sd && st ? new Date(sd + 'T' + st) : null, e = ed && et ? new Date(ed + 'T' + et) : null;
          const mins = s && e ? Math.round((e - s) / 60000) : null;
          const dur = mins == null ? '' : mins <= 0 ? '' : (mins >= 1440 ? Math.floor(mins / 1440) + 'd ' : '') + Math.floor((mins % 1440) / 60) + 'h' + (mins % 60 ? ' ' + (mins % 60) + 'm' : '');
          return { sd, ed, st, et, start: s, end: e, mins, dur, invalid: mins != null && mins <= 0 };
        };

        // --- PLAN AMENDMENTS: apply a correction file to one saved plan, keeping a full audit trail ---
        // File: { _type:'wdfpv_plan_amendment', amendmentId, operationId, amendedBy, amendedOn, summary, changes:[...] }
        // Change ops: set | append | prepend (strings) | copyMapPinCoords | flights | unsign | pilotArn
        const amendShort = (v) => {
          if (v === undefined || v === null || v === '') return '—';
          if (typeof v === 'boolean') return v ? 'Yes' : 'No';
          if (Array.isArray(v)) return v.length && typeof v[0] !== 'object' ? v.join(', ') : v.length + ' item(s)';
          if (typeof v === 'object') {
            if (v.name) return v.name + (v.reocNumber ? ' · ' + v.reocNumber : '') + (v.companyArn ? ' · ARN ' + v.companyArn : '');
            if (v.rpa !== undefined) return (v.enabled ? '' : '(off) ') + (v.rpa || '—') + (v.weight ? ' @ ' + v.weight + ' kg' : '') + (v.useAero ? ', aero' : ', freefall');
            const ks = Object.keys(v); return ks.length ? ks.join(', ') : '—';
          }
          const t = String(v).replace(/\s+/g, ' ').trim();
          return t.length > 90 ? t.slice(0, 87) + '…' : t;
        };
        const amendGet = (o, path) => path.split('.').reduce((a, k) => (a == null ? undefined : a[k]), o);
        const amendSet = (o, path, v) => {
          const ks = path.split('.'); let c = o;
          ks.slice(0, -1).forEach(k => { if (c[k] == null || typeof c[k] !== 'object') c[k] = {}; c = c[k]; });
          c[ks[ks.length - 1]] = v;
        };
        const applyPlanAmendment = (planIn, amend, dbIn) => {
          const plan = JSON.parse(JSON.stringify(planIn));
          const pilots = JSON.parse(JSON.stringify((dbIn && dbIn.pilots) || []));
          const rec = []; const warn = [];
          (amend.changes || []).forEach((c, i) => {
            const why = c.reason || '';
            if (c.op === 'set' || c.op === 'append' || c.op === 'prepend') {
              const before = amendGet(plan, c.path);
              let after = c.value;
              if (c.op === 'append') after = (before ? String(before).replace(/\s+$/, '') + '\n\n' : '') + c.value;
              if (c.op === 'prepend') after = c.value + (before ? '\n\n' + before : '');
              amendSet(plan, c.path, JSON.parse(JSON.stringify(after)));
              rec.push({ field: c.label || c.path, from: c.fromDisplay || amendShort(before), to: c.display ? c.display : c.op === 'set' ? amendShort(after) : (c.op === 'append' ? 'appended: ' : 'added before: ') + amendShort(c.value), reason: why });
            } else if (c.op === 'copyMapPinCoords') {
              const md = plan.mapData || {}; const ov = plan.overview || (plan.overview = {});
              const fmt = (p) => p.lat.toFixed(6) + ', ' + p.lng.toFixed(6);
              [['launches', 'launchSites', 'Launch'], ['recoveries', 'recoverySites', 'Recovery']].forEach(([pk, sk, nm]) => {
                const pins = (md[pk] || []).filter(p => p.lat != null);
                if (!pins.length) { warn.push('No ' + nm.toLowerCase() + ' pins with GPS on the map — ' + sk + ' not changed.'); return; }
                const before = (ov[sk] || []).map(x => x.coords).join(' | ');
                ov[sk] = pins.map((p, k) => ({ id: k + 1, label: (ov[sk] && ov[sk][k] && ov[sk][k].label) || p.label || (nm + ' ' + (k + 1)), coords: fmt(p) }));
                rec.push({ field: nm + ' site coordinates', from: amendShort(before), to: ov[sk].map(x => x.coords).join(' | '), reason: why });
              });
            } else if (c.op === 'flights') {
              const fl = (((plan.log || {}).rpaLogs || {})[c.rpa] || {}).flights;
              if (!fl || !fl.length) { warn.push('No logged flights for "' + c.rpa + '" — change ' + (i + 1) + ' skipped.'); return; }
              const [a, b] = c.range || [1, fl.length];
              if (b > fl.length) warn.push(c.rpa + ': range ' + a + '–' + b + ' is beyond the ' + fl.length + ' logged flights; applied to ' + a + '–' + fl.length + '.');
              const parts = [];
              for (let n = a; n <= Math.min(b, fl.length); n++) {
                const f = fl[n - 1];
                Object.entries(c.set || {}).forEach(([k, v]) => { f[k] = v; });
                Object.entries(c.segments || {}).forEach(([name, patch]) => {
                  const sg = (f.segments || []).find(x => x.name === name);
                  if (sg) Object.assign(sg, patch); else warn.push(c.rpa + ' flight ' + n + ': no "' + name + '" segment.');
                });
                if (c.note) f.amendNote = c.note;
              }
              if (c.set) parts.push(Object.entries(c.set).map(([k, v]) => (k === 'oonp' ? (v ? 'OONP' : 'Non-OONP') : k + ' = ' + amendShort(v))).join(', '));
              if (c.segments) parts.push(Object.entries(c.segments).map(([nm, pt]) => nm + ' max ' + pt.maxFt + ' ft').join(', '));
              rec.push({ field: c.rpa + ' flights ' + (a === b ? '#' + a : '#' + a + '–' + Math.min(b, fl.length)), from: 'as logged', to: parts.join(' · '), reason: why });
            } else if (c.op === 'risks') {
              const rs = plan.risks || (plan.risks = []);
              (c.remove || []).forEach(ref => {
                const k = rs.findIndex(r => r.refNo === ref);
                if (k < 0) { warn.push('Risk ' + ref + ' not found — not removed.'); return; }
                rec.push({ field: 'Risk ' + ref, from: amendShort(rs[k].hazard), to: 'removed', reason: (c.why && c.why[ref]) || why });
                rs.splice(k, 1);
              });
              Object.entries(c.update || {}).forEach(([ref, patch]) => {
                const r = rs.find(x => x.refNo === ref);
                if (!r) { warn.push('Risk ' + ref + ' not found — not updated.'); return; }
                const changed = Object.keys(patch).filter(k => r[k] !== patch[k]);
                rec.push({ field: 'Risk ' + ref + ' (' + changed.join(', ') + ')', from: amendShort(changed.map(k => r[k]).join(' / ')), to: amendShort(changed.map(k => patch[k]).join(' / ')), reason: (c.why && c.why[ref]) || why });
                Object.assign(r, patch);
              });
              (c.add || []).forEach((r, k) => {
                rs.push({ id: Date.now() + k + Math.random(), riskOwner: 'RPIC', ...r });
                rec.push({ field: 'Risk ' + (r.refNo || ''), from: '—', to: 'added: ' + amendShort(r.hazard), reason: (c.why && c.why[r.refNo]) || why });
              });
              rs.sort((a, b) => String(a.refNo || '').localeCompare(String(b.refNo || ''), undefined, { numeric: true }));
            } else if (c.op === 'unsign') {
              const ap = plan.approval || (plan.approval = {});
              const before = (ap.crpSigned ? 'CRP signed ' + (ap.crpDate || '') : 'CRP unsigned') + ' / ' + (ap.rpSigned ? 'RPIC signed ' + (ap.rpDate || '') : 'RPIC unsigned');
              Object.assign(ap, { crpSigned: false, crpDate: '', rpSigned: false, rpDate: '' });
              rec.push({ field: 'Authorisation signatures', from: before, to: 'cleared — re-sign required', reason: why });
            } else if (c.op === 'pilotArn') {
              const pl = pilots.find(x => x.name === c.name);
              if (pl) { rec.push({ field: 'Personnel database: ' + c.name + ' ARN', from: pl.arn || '—', to: c.arn, reason: why }); pl.arn = c.arn; }
              else { pilots.push({ name: c.name, arn: c.arn, phone: '', email: '' }); rec.push({ field: 'Personnel database: ' + c.name, from: '—', to: 'added, ARN ' + c.arn, reason: why }); }
            } else warn.push('Unknown change type "' + c.op + '" — skipped.');
          });
          plan.amendments = [...(plan.amendments || []), {
            id: amend.amendmentId, date: amend.amendedOn || localISODate(),
            by: amend.amendedBy || '', summary: amend.summary || '', changes: rec,
          }];
          return { plan, pilots, rec, warn };
        };

        // --- NOTAM SUMMARY FOR PRINT/PDF ---
        // Keeps the NAIPS location header plus the first few NOTAMs (paragraphs), each trimmed to a few lines.
        const NOTAM_FULL_NOTE = 'SUMMARY ONLY — refer to the online software version for the full NOTAM text.';
        const summariseNotams = (text, { maxNotams = 3, maxLines = 6 } = {}) => {
          const t = (text || '').replace(/\r/g, '').trim();
          if (!t) return { text: '', truncated: false };
          let header = '', body = t;
          const hm = t.match(/^NAIPS location briefing:[\s\S]*?\[Paste NOTAMs from NAIPS below\]\n?/);
          if (hm) { header = hm[0].replace('\n[Paste NOTAMs from NAIPS below]', '').trim(); body = t.slice(hm[0].length).trim(); }
          let paras = body.split(/\n\s*\n/).map(x => x.trim()).filter(Boolean);
          // No blank lines between NOTAMs? split on NOTAM serial lines (e.g. "C0123/26 NOTAMN")
          if (paras.length <= 1 && body) {
            const bySerial = body.split(/\n(?=[A-Z]\d{3,4}\/\d{2}\b)/).map(x => x.trim()).filter(Boolean);
            if (bySerial.length > 1) paras = bySerial;
          }
          let truncated = paras.length > maxNotams;
          const kept = paras.slice(0, maxNotams).map(pp => {
            // ICAO-format NOTAM: keep serial, A) location, B)/C) times, E) text (trimmed), F)/G) limits; drop Q) line
            if (/(^|\n)E\)\s/.test(pp)) {
              const parts = pp.split(/\n(?=[A-GQ]\)\s)/);
              const head = /^[A-GQ]\)\s/.test(parts[0]) ? '' : parts.shift();
              const f = {}; parts.forEach(x => { f[x[0]] = x.trim(); });
              let e = (f.E || '').replace(/\s*\n\s*/g, ' ');
              if (e.length > 280) { truncated = true; e = e.slice(0, 280).trim() + ' …'; }
              if (f.Q || (head && head.split('\n').length > 1)) truncated = true;
              return [head && head.split('\n')[0], f.A, [f.B, f.C].filter(Boolean).join('  '), e, [f.F, f.G].filter(Boolean).join('  ')].filter(Boolean).join('\n');
            }
            const lines = pp.split('\n');
            if (lines.length > maxLines) { truncated = true; return lines.slice(0, maxLines).join('\n') + '\n  …'; }
            if (pp.length > 600) { truncated = true; return pp.slice(0, 600) + ' …'; }
            return pp;
          });
          const more = paras.length > maxNotams ? `\n\n+ ${paras.length - maxNotams} more NOTAM${paras.length - maxNotams > 1 ? 's' : ''} not shown.` : '';
          return { text: [header, kept.join('\n\n')].filter(Boolean).join('\n\n') + more, truncated };
        };

        // --- AUSTRALIAN AERODROME DATABASE (ICAO 4-letter codes) ---
        // ~2,000 Y-coded locations (airports, ALAs, helipads) from OurAirports public data, embedded for offline use.
        // Format: ICAO|Name|Town|IATA|Type|Lat|Lng  — Type L=major airport, M=airport, S=aerodrome/ALA, H=helipad/HLS, W=seaplane
