        const geoInside = (lat, lng, g) => geoPolys(g).some(p => p.length && geoInRing(lat, lng, p[0]) && !p.slice(1).some(h => geoInRing(lat, lng, h)));
        const geoEdgeDistM = (lat, lng, g) => {
          let best = Infinity; const kx = Math.cos(lat * Math.PI / 180) * 111320, ky = 110540;
          geoPolys(g).forEach(p => p.forEach(ring => { for (let i = 1; i < ring.length; i++) {
            const ax = (ring[i - 1][0] - lng) * kx, ay = (ring[i - 1][1] - lat) * ky, bx = (ring[i][0] - lng) * kx, by = (ring[i][1] - lat) * ky;
            const dx = bx - ax, dy = by - ay, t = Math.max(0, Math.min(1, -(ax * dx + ay * dy) / ((dx * dx + dy * dy) || 1e-9)));
            best = Math.min(best, Math.hypot(ax + t * dx, ay + t * dy));
          } }));
          return best;
        };
        const fmtDistM = (m) => m >= 10000 ? (m / 1000).toFixed(1) + ' km' : Math.round(m).toLocaleString('en-AU') + ' m';
        const fmtBrg = (b) => String(Math.round(b) % 360).padStart(3, '0') + '°';
        // Turns OpenAIP airspaces + airports into the check shown in the JSA
        const buildAirspaceCheck = (lat, lng, asItems, apItems) => {
          const asLabel = (a) => {
            const t = OAIP_AS_TYPE[a.type] != null ? OAIP_AS_TYPE[a.type] : (typeof a.type === 'string' ? a.type : 'Airspace');
            const c = OAIP_CLASS[a.icaoClass];
            return { name: a.name || t, type: t, cls: c || null, lower: oaipLimit(a.lowerLimit), upper: oaipLimit(a.upperLimit), lowerFt: oaipLimitFt(a.lowerLimit),
              special: [1, 2, 3, 31, 17, 18, 19].includes(a.type) };
          };
          const inside = [], nearby = [];
          (asItems || []).forEach(a => {
            if (!a || !a.geometry) return;
            if ([10, 11, 27, 33].includes(a.type)) return; // FIR/UIR/ACC/FIS sectors cover everything
            if (geoInside(lat, lng, a.geometry)) inside.push(asLabel(a));
            else { const d = geoEdgeDistM(lat, lng, a.geometry); if (d <= 3000) nearby.push({ ...asLabel(a), dist: d }); }
          });
          inside.sort((x, y) => x.lowerFt - y.lowerFt); nearby.sort((x, y) => x.dist - y.dist);
          const aerodromes = (apItems || []).map(ap => {
            const c = ap.geometry && ap.geometry.coordinates; if (!c) return null;
            const d = geoDistM(lat, lng, c[1], c[0]); if (d > 15000) return null;
            const freqs = (ap.frequencies || []).map(f => ({ value: String(f.value || '').trim(), type: OAIP_FREQ_TYPE[f.type] != null ? OAIP_FREQ_TYPE[f.type] : '', name: (f.name || '').trim(), primary: !!f.primary })).filter(f => f.value);
            const heli = [4, 7].includes(ap.type);
            return { name: ap.name || 'Unnamed', icao: ap.icaoCode || '', kind: OAIP_AP_TYPE[ap.type] || (heli ? 'Heliport' : 'Aerodrome'), heli, dist: d, brg: geoBearing(lat, lng, c[1], c[0]), freqs, controlled: freqs.some(f => /tower|approach|ground|delivery/i.test(f.type + ' ' + f.name)) };
          }).filter(Boolean).sort((x, y) => x.dist - y.dist).slice(0, 8);
          const controlledAs = inside.filter(a => a.cls && a.cls !== 'G' && !a.special);
          const special = inside.filter(a => a.special);
          return { lat, lng, inside, nearby, aerodromes, controlledAs, special };
        };
        const airspaceCheckText = (ck) => {
          const lim = (a) => a.lower + ' to ' + a.upper;
          const parts = [];
          const ctl = ck.controlledAs.filter(a => a.lowerFt <= 400);
          parts.push(ctl.length ? ctl.map(a => 'Class ' + a.cls + ' ' + a.name + ' (' + lim(a) + ')').join('; ') : 'Class G at the surface' + (ck.controlledAs.length ? ' (controlled airspace above: ' + ck.controlledAs.map(a => 'Class ' + a.cls + ' from ' + a.lower).join(', ') + ')' : ''));
          ck.special.forEach(a => parts.push(a.name + ' ' + a.type.toUpperCase() + ' ' + lim(a)));
          const aero = ck.aerodromes.map(a => a.name + (a.icao ? ' (' + a.icao + ')' : '') + ' ' + fmtBrg(a.brg) + '/' + fmtDistM(a.dist) + (a.dist <= 5500 && !a.heli ? ' (within 5.5 km)' : ''));
          const radio = ck.aerodromes.filter(a => a.freqs.length).slice(0, 4).map(a => (a.icao || a.name) + ' ' + a.freqs.slice(0, 3).map(f => (f.type || f.name || 'Freq') + ' ' + f.value).join(', '));
          return { airspace: parts.join('; '), aerodromes: aero.join('; '), radio: radio.join('; ') };
        };
        // ── Log dump: work out which aircraft a radio log belongs to (v5.29) ──
        // 1) EdgeTX names logs "<radio model>-YYYY-MM-DD-HHMMSS.csv": match the model name to an aircraft's
        //    "Radio model" (or the aircraft name). 2) Otherwise use the battery: the starting RxBt voltage
        //    gives the possible cell counts (3.30–4.45 V per cell), matched to each aircraft's "Battery" setting.
        //    Aircraft on this job are tried before the rest of the fleet.
        const packCells = (id) => { const m = /^\s*(\d{1,2})\s*s(?![a-z])/i.exec(String(id || '')); return m ? parseInt(m[1], 10) : 0; };
        const dumpNorm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
        const edgeTxModel = (fileName) => String(fileName || '').replace(/\.csv$/i, '').replace(/-\d{4}-\d{2}-\d{2}-\d{6}$/, '').trim();
        const cellCandidates = (v) => { const out = []; if (!(v > 0)) return out; for (let n = 1; n <= 14; n++) { const c = v / n; if (c >= 3.3 && c <= 4.45) out.push(n); } return out; };
        const likelyCells = (v) => { const c = cellCandidates(v); const typ = c.filter(n => v / n >= 3.7 && v / n <= 4.4); return (typ.length ? typ : c)[0] || null; };
        // ── Import / upload progress (v5.41) ──
        const wdProgress = (() => {
          let cur = null, hideT = null;
          const emit = () => { try { window.dispatchEvent(new CustomEvent('wd-progress', { detail: cur })); } catch (e) {} };
          const upd = (patch) => { if (!cur) return; cur = { ...cur, ...patch }; emit(); };
          return {
            start(title, total, bytes) { clearTimeout(hideT); cur = { title, total: total || 1, i: 0, name: '', bytes: bytes || 0, doneBytes: 0, curBytes: 0, phase: 'Reading', state: 'run' }; emit(); },
            file(i, name) { upd({ i, name, curBytes: 0, phase: 'Reading' }); },
            bytes(n) { upd({ curBytes: n }); },
            fileDone(size) { if (cur) upd({ doneBytes: cur.doneBytes + (size || 0), curBytes: 0 }); },
            phase(p) { upd({ phase: p }); },
            finish(msg) { if (!cur) return; upd({ state: 'done', phase: msg || 'Done', i: cur.total, doneBytes: cur.bytes, curBytes: 0 }); clearTimeout(hideT); hideT = setTimeout(() => { cur = null; emit(); }, 1400); },
            fail(msg) { if (!cur) return; upd({ state: 'error', phase: msg || 'Failed' }); clearTimeout(hideT); hideT = setTimeout(() => { cur = null; emit(); }, 4000); },
          };
        })();
        const wdTick = () => new Promise(r => setTimeout(r, 30)); // lets the progress bar paint between files
        // Reads files one at a time, reporting progress. as: 'text' | 'url'
        const wdReadFiles = async (files, as, title) => {
          const list = [...files], bytes = list.reduce((s, f) => s + (f.size || 0), 0), out = [];
          wdProgress.start(title, list.length, bytes);
          for (let i = 0; i < list.length; i++) {
            const f = list[i]; wdProgress.file(i, f.name); await wdTick();
            let result = null, error = '';
            try {
              result = await new Promise((res, rej) => { const r = new FileReader(); r.onprogress = (e) => wdProgress.bytes(e.loaded); r.onload = () => res(r.result); r.onerror = () => rej(new Error('could not read file')); as === 'url' ? r.readAsDataURL(f) : r.readAsText(f); });
            } catch (e) { error = e.message; }
            wdProgress.fileDone(f.size);
            out.push({ file: f, name: f.name, result, error });
          }
          return out;
        };
        // For single-file FileReader handlers: shows the bar while reading, then closes after the handler runs
        const wdTrackReader = (r, f, title) => {
          if (!f) return;
          wdProgress.start(title, 1, f.size); wdProgress.file(0, f.name);
          r.addEventListener('progress', (e) => wdProgress.bytes(e.loaded));
          r.addEventListener('load', () => { wdProgress.fileDone(f.size); wdProgress.phase('Processing'); });
          r.addEventListener('error', () => wdProgress.fail('Could not read ' + f.name));
          r.addEventListener('loadend', () => setTimeout(() => wdProgress.finish(), 0));
        };
        function WdProgressOverlay() {
          const [p, setP] = useState(null);
          useEffect(() => { const h = (e) => setP(e.detail); window.addEventListener('wd-progress', h); return () => window.removeEventListener('wd-progress', h); }, []);
          if (!p) return null;
          const pct = p.state === 'done' ? 100 : p.bytes > 0 ? Math.min(99, Math.round((p.doneBytes + p.curBytes) / p.bytes * 100)) : Math.round(p.i / p.total * 100);
          const kb = (n) => n > 1048576 ? (n / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.round(n / 1024)) + ' KB';
          const col = p.state === 'error' ? 'bg-red-500' : p.state === 'done' ? 'bg-emerald-500' : 'bg-indigo-500';
          return (
            <div data-testid="wd-progress" data-state={p.state} className="fixed bottom-5 left-1/2 -translate-x-1/2 z-[5000] w-[min(28rem,calc(100vw-2rem))] bg-white border border-slate-200 rounded-xl shadow-2xl px-4 py-3 print:hidden">
              <div className="flex items-center gap-2 text-sm font-semibold text-slate-800">
                <i className={`fa-solid ${p.state === 'done' ? 'fa-circle-check text-emerald-600' : p.state === 'error' ? 'fa-triangle-exclamation text-red-600' : 'fa-spinner fa-spin text-indigo-600'}`}></i>
                <span className="flex-1 truncate">{p.title}</span>
                <span className="font-mono text-xs text-slate-500">{pct}%</span>
              </div>
              <div className="h-2 bg-slate-100 rounded-full mt-2 overflow-hidden"><div className={`h-full ${col} transition-all duration-200`} style={{ width: pct + '%' }}></div></div>
              <div className="text-[11px] text-slate-500 mt-1.5 flex gap-2">
                <span className="truncate flex-1">{p.state === 'run' ? (p.phase === 'Reading' ? 'Reading ' : p.phase + (p.name ? ': ' : '')) + (p.name || '') : p.phase}</span>
                {p.total > 1 && <span className="whitespace-nowrap">{p.state === 'run' ? 'File ' + Math.min(p.i + 1, p.total) : p.total} of {p.total}</span>}
                {p.bytes > 0 && <span className="whitespace-nowrap">{kb(p.bytes)}</span>}
              </div>
            </div>
          );
        }

        const guessAircraft = (t, fileName, fleet, jobRpas) => {
          const fl = fleet || {}, all = Object.keys(fl), job = (jobRpas || []).filter(r => fl[r]);
          const model = edgeTxModel(fileName), mN = dumpNorm(model);
          const cand = cellCandidates(t && t.vStart);
          const cellsOf = (r) => parseInt((fl[r] || {}).cells) || 0;
          if (mN.length >= 3) {
            const byModel = all.filter(r => dumpNorm((fl[r] || {}).radioModel) === mN);
            const byName = byModel.length ? byModel : all.filter(r => dumpNorm(r) === mN);
            if (byName.length === 1) return { rpa: byName[0], why: byModel.length ? 'radio model' : 'aircraft name', cand, model };
          }
          const pick = (list) => {
            const m = list.filter(r => cand.includes(cellsOf(r)));
            if (m.length < 2) return m;
            const sizes = [...new Set(m.map(cellsOf))];
            if (sizes.length > 1) { const typ = sizes.filter(n => t.vStart / n >= 3.7 && t.vStart / n <= 4.4); if (typ.length) return m.filter(r => typ.includes(cellsOf(r))); }
            return m;
          };
          const j = pick(job);
          if (j.length === 1) return { rpa: j[0], why: cellsOf(j[0]) + 'S on this job', cand, model };
          if (j.length > 1) return { rpa: '', why: 'several ' + cellsOf(j[0]) + 'S aircraft on this job', options: j, cand, model };
          const f = pick(all);
          if (f.length === 1) return { rpa: f[0], why: cellsOf(f[0]) + 'S in the fleet (not on this job yet)', cand, model };
          if (f.length > 1) return { rpa: '', why: 'several matching aircraft in the fleet', options: f, cand, model };
          return { rpa: '', why: !(t && t.vStart > 0) ? 'no RxBt voltage in the log' : all.some(r => cellsOf(r)) ? 'no aircraft set to ' + (likelyCells(t.vStart) || '?') + 'S' : 'no battery cell counts set on the fleet yet', cand, model };
        };

        // Builds a planner flight entry from a telemetry summary
        const flightFromTelemetry = (t) => {
          const ft = (m) => String(Math.round((m || 0) * 3.28084));
          return {
            id: Date.now() + Math.random(), source: 'telemetry',
            label: fmtTlmDate(t.startMs) + ' ' + fmtTlmTime(t.startMs) + '–' + fmtTlmTime(t.endMs),
            duration: String(Math.max(1, Math.round(t.durationSec / 60))), batteries: '', showHeights: false,
            segments: [
              { id: Date.now() + Math.random(), name: 'Take-Off', maxFt: ft(t.takeoffMaxM), minFt: '', useRange: false },
              { id: Date.now() + Math.random(), name: 'Flight Operation', maxFt: ft(t.maxAltM), minFt: '', useRange: false },
              { id: Date.now() + Math.random(), name: 'Landing', maxFt: ft(t.landingMaxM), minFt: '', useRange: false },
            ],
            telemetry: t,
          };
        };

        // ── Flight Log import (v5.26) ── merges a WakingDream Flight Log "Export to planner" file into Section 4.
        // Each flight goes to the fleet aircraft it was logged against. A flight that is already here (same telemetry
        // start time) is only filled in — batteries, OONP — never overwritten. Blank starter flights are dropped.
        const mergeFlightLog = ({ log, overview, db, data }) => {
          const fleetKeys = Object.keys(db.fleet || {});
          const findRpa = (name) => { const n = String(name || '').trim().toLowerCase(); return n ? (fleetKeys.find(k => k.toLowerCase() === n) || null) : null; };
          const isBlank = (f) => !(parseInt(f.duration) > 0) && !String(f.batteries || '').trim() && !f.telemetry && !(f.segments || []).some(s => s.maxFt);
          const rpaTypes = [...(overview.rpaTypes || [])], rpaLogs = { ...(log.rpaLogs || {}) };
          const rpaBatteries = { ...(db.rpaBatteries || {}) }, pilots = [...(db.pilots || [])];
          const changes = [], skipped = [], noteLines = [], pilotNames = new Set();
          let same = 0, added = 0, addedSec = 0;
          const knownBatt = () => new Set([...Object.values(rpaBatteries).flat(), ...(db.batteries || [])].map(x => String(x).toLowerCase()));
          (data.flights || []).forEach(fl => {
            const t = fl.plannerTelemetry, lab = '#' + (fl.seq || '?') + ' ' + String(fl.start || '').slice(0, 16).replace('T', ' ');
            if (!t || !t.startMs) { skipped.push(lab + ' — no telemetry summary in the export'); return; }
            let rpa = findRpa(fl.aircraft);
            if (!rpa && !fl.aircraft && rpaTypes.length === 1) rpa = rpaTypes[0];
            if (!rpa) { skipped.push(lab + ' — ' + (fl.aircraft ? `aircraft "${fl.aircraft}" is not in the fleet database` : 'no aircraft chosen in Flight Log')); return; }
            if (!rpaTypes.includes(rpa)) { rpaTypes.push(rpa); changes.push(`Add ${rpa} to this operation's RPA types`); }
            const rl = { duration: '', batteries: '', fpvEnabled: false, flights: [], ...(rpaLogs[rpa] || {}) };
            let flights = [...(rl.flights || [])];
            const batt = (fl.batteryPacks || []).map(b => String(b).trim()).filter(Boolean).join(', ');
            const i = flights.findIndex(f => f.telemetry && f.telemetry.startMs === t.startMs);
            if (i >= 0) {
              const f = flights[i], upd = { ...f }, what = [];
              if (!String(f.batteries || '').trim() && batt) { upd.batteries = batt; what.push('battery ' + batt); }
              if (fl.oonp === true && f.oonp === undefined) { upd.oonp = true; what.push('OONP'); }
              if (what.length) { flights[i] = upd; changes.push(`${rpa} ${lab}: add ${what.join(', ')}`); } else same++;
            } else {
              const nf = { ...flightFromTelemetry(t), batteries: batt, flightLogId: fl.id || '' };
              if (fl.oonp === true) nf.oonp = true;
              flights = flights.filter(f => !isBlank(f)); flights.push(nf); added++; addedSec += t.durationSec || 0;
              changes.push(`${rpa}: new flight ${lab} (${fmtMmSs(t.durationSec)}${batt ? ' · ' + batt : ''}${fl.oonp === true ? ' · OONP' : ''})`);
            }
            rpaLogs[rpa] = { ...rl, flights };
            (fl.batteryPacks || []).forEach(b => { b = String(b).trim(); if (b && !knownBatt().has(b.toLowerCase())) { rpaBatteries[rpa] = [...(rpaBatteries[rpa] || []), b]; changes.push(`Add battery ${b} to ${rpa} in the database`); } });
            if (fl.pilot) { pilotNames.add(fl.pilot); if (!pilots.some(p => p.name.toLowerCase() === fl.pilot.toLowerCase())) { pilots.push({ name: fl.pilot, arn: fl.pilotArn || '', email: '', phone: '' }); changes.push(`Add pilot ${fl.pilot}${fl.pilotArn ? ' (ARN ' + fl.pilotArn + ')' : ''} to the database`); } }
            if (fl.notes && String(fl.notes).trim()) noteLines.push(`Flight Log ${lab}: ${String(fl.notes).trim()}`);
          });
          const newLog = { ...log, rpaLogs };
          if (!String(log.crewRP || '').trim() && pilotNames.size === 1) { newLog.crewRP = [...pilotNames][0]; changes.push('Primary RP: ' + newLog.crewRP); }
          const fresh = noteLines.filter(l => !String(log.comments || '').includes(l));
          if (fresh.length) { newLog.comments = (String(log.comments || '').trim() ? String(log.comments).trim() + '\n' : '') + fresh.join('\n'); changes.push(`Add ${fresh.length} flight note${fresh.length === 1 ? '' : 's'} to Comments`); }
          return { log: newLog, rpaTypes, rpaTypesChanged: rpaTypes.length !== (overview.rpaTypes || []).length, rpaBatteries, pilots, changes, skipped, same, added, addedSec };
        };

        // Logged time per pilot, battery and aircraft, worked out from Completed Flight Records (v5.26).
        // Telemetry flights use their exact armed time; manual flights use the minutes entered.
        const loggedTimeStats = (records) => {
          const pil = {}, bat = {}, acft = {};
          (records || []).forEach(rec => {
            const lg = rec.log || {}, ov = rec.overview || {}, pilot = String(lg.crewRP || ov.rpic || '').trim();
            Object.entries(lg.rpaLogs || {}).forEach(([rpa, rl]) => (rl.flights || []).forEach(f => {
              const sec = f.telemetry && f.telemetry.durationSec > 0 ? f.telemetry.durationSec : (parseInt(f.duration) || 0) * 60;
              if (!(sec > 0)) return;
              const when = (f.telemetry && f.telemetry.startMs) || Date.parse(rec.completedAt || '') || 0;
              const add = (o, k) => { const x = o[k] = o[k] || { flights: 0, sec: 0, last: 0 }; x.flights++; x.sec += sec; x.last = Math.max(x.last, when); return x; };
              if (pilot) add(pil, pilot);
              add(acft, rpa);
              String(f.batteries || '').split(',').map(s => s.trim()).filter(Boolean).forEach(b => {
                const x = add(bat, b); x.rpa = x.rpa || rpa;
                const t = f.telemetry; if (t && t.vMin > 0 && t.cells) { const c = t.vMin / t.cells; x.minCell = x.minCell ? Math.min(x.minCell, c) : c; }
              });
            }));
          });
          return { pil, bat, acft };
        };
        const fmtHrsMin = (s) => { s = Math.round(s || 0); const hh = Math.floor(s / 3600), mm = Math.floor((s % 3600) / 60); return hh ? `${hh}h ${String(mm).padStart(2, '0')}m` : `${mm}m ${String(s % 60).padStart(2, '0')}s`; };

        // ── TelemetryPanel ── read-only summary of an imported telemetry flight
        function TelemetryPanel({ t, kg, oonp, onRemove, limitCtx, title }) {
          const [detail, setDetail] = useState(false);
          const tr = (t.trace || []).filter(p => p && p[0] != null);
          const W = 300, H = 90, L = 28, R = 26, T = 8, B = 16, cw = W - L - R, ch = H - T - B;
          const dur = Math.max(1, t.durationSec || (tr.length ? tr[tr.length - 1][0] : 1));
          const topA = Math.max(10, Math.ceil(((t.maxAltM || 0) * 1.15) / 10) * 10);
          const topS = Math.max(20, Math.ceil(((t.maxSpeedKmh || 0) * 1.1) / 20) * 20);
          const X = (s) => L + (s / dur) * cw, YA = (m) => T + ch - (Math.max(0, m) / topA) * ch, YS = (k) => T + ch - (Math.max(0, k) / topS) * ch;
          const altPts = tr.filter(p => p[1] != null).map(p => X(p[0]).toFixed(1) + ',' + YA(p[1]).toFixed(1));
          const spdPts = tr.filter(p => p[2] != null).map(p => X(p[0]).toFixed(1) + ',' + YS(p[2]).toFixed(1));
          const area = altPts.length ? `${L},${YA(0)} ${altPts.join(' ')} ${X(dur).toFixed(1)},${YA(0)}` : '';
          // GPS track (flat-earth projection is fine at this scale)
          const gp = tr.filter(p => p[3] != null);
          let track = null;
          if (gp.length > 1) {
            const lat0 = gp[0][3], k = Math.cos(lat0 * Math.PI / 180);
            const xs = gp.map(p => p[4] * k), ys = gp.map(p => p[3]);
            const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
            const span = Math.max(maxX - minX, maxY - minY, 1e-5), S = 84 / span;
            const px = (i) => 8 + (xs[i] - minX) * S + (84 - (maxX - minX) * S) / 2, py = (i) => 8 + (maxY - ys[i]) * S + (84 - (maxY - minY) * S) / 2;
            const hm = t.home ? [8 + (t.home[1] * k - minX) * S + (84 - (maxX - minX) * S) / 2, 8 + (maxY - t.home[0]) * S + (84 - (maxY - minY) * S) / 2] : [px(0), py(0)];
            track = { d: gp.map((_, i) => px(i).toFixed(1) + ',' + py(i).toFixed(1)).join(' '), hm, end: [px(gp.length - 1), py(gp.length - 1)] };
          }
          const ke = telemetryKe(t, kg);
          const keLim = oonp === true ? 34 : null;
          const st = (label, value, sub, warn) => (
            <div className="bg-white border border-slate-200 rounded px-2 py-1 min-w-0">
              <div className="text-[9px] font-bold text-slate-400 uppercase tracking-wider truncate">{label}</div>
              <div className={`text-xs font-bold font-mono ${warn ? 'text-red-600' : 'text-slate-800'}`}>{value}</div>
              {sub && <div className="text-[9px] text-slate-400 truncate">{sub}</div>}
            </div>
          );
          const dash = (v, u = '') => (v === null || v === undefined || Number.isNaN(v)) ? '—' : v + u;
          return (
            <div className="px-3 py-2 bg-cyan-50/60 border-b border-cyan-100">
              <div className="flex items-center justify-between gap-2 mb-2 flex-wrap">
                <div className="text-[11px] font-semibold text-cyan-900 flex items-center gap-1.5 flex-wrap">
                  <i className="fa-solid fa-satellite-dish text-cyan-600"></i>
                  Telemetry · {fmtTlmDate(t.startMs)} {fmtTlmTime(t.startMs)}–{fmtTlmTime(t.endMs)}
                  <span className="text-cyan-700/70 font-normal">({fmtMmSs(t.durationSec)} armed · radio clock {t.clock === 'local' ? 'local' : 'UTC'})</span>
                </div>
                <div className="flex items-center gap-2">
                  <button type="button" data-tlm-open="1" onClick={() => setDetail(true)} className="text-[11px] font-semibold px-2 py-0.5 rounded bg-cyan-600 text-white hover:bg-cyan-700"><i className="fa-solid fa-up-right-and-down-left-from-center mr-1 text-[9px]"></i>Details</button>
                  {t.file && <span className="text-[10px] text-slate-400 font-mono truncate max-w-[180px]" title={t.file}>{t.file}</span>}
                  <button onClick={onRemove} title="Remove telemetry from this flight (keeps the manual entries)" className="text-[10px] text-slate-400 hover:text-red-500">Remove</button>
                </div>
              </div>
              <div className="grid grid-cols-3 sm:grid-cols-6 gap-1.5 mb-2">
                {st('Max alt', dash(t.maxAltM, ' m'), t.maxAltM != null ? Math.round(t.maxAltM * 3.28084) + (t.altRef === 'landing' ? ' ft above landing point' : t.altRef === 'lowest' ? ' ft above lowest point' : ' ft above take-off') : '', t.maxAltM > 120)}
                {st('Max speed', dash(t.maxSpeedKmh, ' km/h'), 'GPS ground speed')}
                {st('Max distance', dash(t.maxDistM, ' m'), t.pathM ? 'path ' + (t.pathM / 1000).toFixed(2) + ' km' : 'from home')}
                {st('Battery', t.vStart != null ? `${t.vStart}→${t.vEnd} V` : '—', [t.cells ? t.cells + 'S' : '', t.vMin != null ? 'sag ' + t.vMin + ' V' : ''].filter(Boolean).join(' · '))}
                {st('Used', dash(t.mahUsed, ' mAh'), t.maxCurrA != null ? `max ${t.maxCurrA} A · avg ${t.avgCurrA} A` : '')}
                {st('Link', t.minRq != null ? `RQ ${t.minRq}%` : '—', [t.minRss != null ? 'min ' + t.minRss + ' dBm' : '', t.maxTpwr != null ? t.maxTpwr + ' mW' : ''].filter(Boolean).join(' · '), t.minRq != null && t.minRq < 50)}
              </div>
              <div className="flex gap-2 items-stretch flex-wrap sm:flex-nowrap">
                <div className="flex-1 min-w-[240px] bg-white border border-slate-200 rounded">
                  <svg viewBox={`0 0 ${W} ${H}`} width="100%" style={{ display: 'block' }}>
                    <line x1={L} x2={L + cw} y1={YA(0)} y2={YA(0)} stroke="#94a3b8" strokeWidth="0.6" />
                    <line x1={L} x2={L + cw} y1={YA(topA / 2)} y2={YA(topA / 2)} stroke="#e2e8f0" strokeWidth="0.5" />
                    <line x1={L} x2={L + cw} y1={YA(topA)} y2={YA(topA)} stroke="#e2e8f0" strokeWidth="0.5" />
                    {topA >= 120 && <line x1={L} x2={L + cw} y1={YA(120)} y2={YA(120)} stroke="#dc2626" strokeWidth="0.6" strokeDasharray="2,1.5" />}
                    {area && <polygon points={area} fill="#1d76d2" fillOpacity="0.18" />}
                    {altPts.length > 1 && <polyline points={altPts.join(' ')} fill="none" stroke="#1d76d2" strokeWidth="1.3" strokeLinejoin="round" />}
                    {spdPts.length > 1 && <polyline points={spdPts.join(' ')} fill="none" stroke="#f59e0b" strokeWidth="0.9" strokeLinejoin="round" opacity="0.9" />}
                    {(t.events || []).map((e, i) => <line key={i} x1={X(e.t)} x2={X(e.t)} y1={T} y2={T + ch} stroke="#dc2626" strokeWidth="0.8" />)}
                    <text x={L - 3} y={YA(topA) + 3} fontSize="7" textAnchor="end" fill="#1d76d2">{topA}m</text>
                    <text x={L - 3} y={YA(0) + 3} fontSize="7" textAnchor="end" fill="#64748b">0</text>
                    <text x={L + cw + 3} y={YS(topS) + 3} fontSize="7" fill="#b45309">{topS}</text>
                    <text x={L + cw + 3} y={YS(0) + 3} fontSize="7" fill="#b45309">km/h</text>
                    <text x={L} y={H - 4} fontSize="7" fill="#64748b">0:00</text>
                    <text x={L + cw} y={H - 4} fontSize="7" textAnchor="end" fill="#64748b">{fmtMmSs(dur)}</text>
                    <text x={L + cw / 2} y={H - 4} fontSize="7" textAnchor="middle" fill="#64748b"><tspan fill="#1d76d2">— altitude</tspan>  <tspan fill="#b45309">— speed</tspan></text>
                  </svg>
                </div>
                {track && (
                  <div className="bg-white border border-slate-200 rounded flex-shrink-0 p-0.5">
                    {window.L ? <TlmMiniMap t={t} onOpen={() => setDetail(true)} /> : (
                      <svg viewBox="0 0 100 100" width="100" height="100" style={{ display: 'block' }}>
                        <polyline points={track.d} fill="none" stroke="#0e7490" strokeWidth="1.2" strokeLinejoin="round" />
                        <circle cx={track.hm[0]} cy={track.hm[1]} r="3" fill="#16a34a" stroke="white" strokeWidth="1" />
                        <circle cx={track.end[0]} cy={track.end[1]} r="2.5" fill="#dc2626" stroke="white" strokeWidth="1" />
                      </svg>
                    )}
                  </div>
                )}
              </div>
              <div className="mt-1.5 text-[10px] text-slate-600 space-y-0.5">
                {ke != null && (
                  <div className={keLim && ke > keLim ? 'text-red-700 font-semibold' : ''}>
                    <i className="fa-solid fa-bolt text-[9px] mr-1"></i>
                    Peak KE (estimate, no drag, {kg} kg): <b>{ke.toFixed(1)} J</b> at {Math.round(t.keAt.v * 3.6)} km/h and {t.keAt.h} m
                    {keLim ? (ke > keLim ? ' — over 34 J: this flight should not be logged as over consenting people' : ' — within 34 J') : ''}
                  </div>
                )}
                {ke == null && <div className="text-slate-400">Add this aircraft's weight in Database &amp; Settings to see a kinetic-energy estimate.</div>}
                {flightLimitIssues(t, { ...(limitCtx || {}), kg, oonp }).map((x, i) => (
                  <div key={'lim' + i} className={x.sev === 'red' ? 'text-red-700 font-semibold' : 'text-amber-700 font-semibold'} data-testid="flight-limit-issue">⚠ {x.text}</div>
                ))}
                {t.minSats != null && <div>GPS sats {t.minSats}–{t.maxSats}{t.home ? ` · home ${t.home[0].toFixed(5)}, ${t.home[1].toFixed(5)}` : ''}</div>}
                {(t.events || []).map((e, i) => <div key={i} className="text-red-700 font-semibold">⚠ {fmtMmSs(e.t)}: {e.text}</div>)}
                {(t.notes || []).map((n, i) => <div key={'n' + i} className="text-amber-700">ⓘ {n}</div>)}
              </div>
              {detail && <TlmDetail t={t} kg={kg} oonp={oonp} limitCtx={limitCtx} title={title} onClose={() => setDetail(false)} />}
            </div>
          );
        }

        // ── Satellite map for flight tracks (v5.41) ──
        const wdSatTiles = (L, m) => {
          const google = L.tileLayer('https://mt{s}.google.com/vt/lyrs=y&hl=en&x={x}&y={y}&z={z}', { subdomains: ['0','1','2','3'], attribution: 'Imagery © Google', maxZoom: 21 }).addTo(m);
          let ok = 0, err = 0, sw = false;
          google.on('tileload', () => { ok++; });
          google.on('tileerror', () => { err++; if (!sw && ok === 0 && err >= 4) { sw = true; m.removeLayer(google); L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', { attribution: 'Imagery © Esri', maxZoom: 21, maxNativeZoom: 19 }).addTo(m); } });
        };
        const tlmTrack = (t) => (t.trace || []).filter(p => p && p[3] != null && p[4] != null).map(p => [p[3], p[4]]);
        // Small, non-interactive satellite map; only built once it scrolls into view (a log can hold many flights)
        function TlmMiniMap({ t, onOpen }) {
          const ref = useRef(null);
          useEffect(() => {
            const el = ref.current, L = window.L; if (!el || !L) return;
            let m = null;
            const build = () => {
              if (m) return; const pts = tlmTrack(t); if (pts.length < 2) return;
              m = L.map(el, { zoomControl: false, attributionControl: false, dragging: false, scrollWheelZoom: false, doubleClickZoom: false, boxZoom: false, keyboard: false, touchZoom: false });
              wdSatTiles(L, m);
              const line = L.polyline(pts, { color: '#22d3ee', weight: 2.5, opacity: 0.95 }).addTo(m);
              const home = t.home || pts[0];
              L.circleMarker(home, { radius: 4, color: '#fff', weight: 1.5, fillColor: '#16a34a', fillOpacity: 1 }).addTo(m);
              L.circleMarker(pts[pts.length - 1], { radius: 3.5, color: '#fff', weight: 1.5, fillColor: '#dc2626', fillOpacity: 1 }).addTo(m);
              m.fitBounds(line.getBounds(), { padding: [8, 8], maxZoom: 19 });
            };
            let io = null;
            if ('IntersectionObserver' in window) { io = new IntersectionObserver((es) => { if (es.some(e => e.isIntersecting)) { build(); io.disconnect(); } }, { rootMargin: '200px' }); io.observe(el); } else build();
            return () => { if (io) io.disconnect(); if (m) m.remove(); };
          }, [t]);
          return <div ref={ref} data-tlm-minimap="1" onClick={onOpen} title="GPS track on satellite imagery — click for the detailed view" className="w-[150px] h-[110px] rounded bg-slate-200 cursor-pointer overflow-hidden" style={{ zIndex: 0 }}></div>;
        }

        // Full-screen detail view of one telemetry flight
        function TlmDetail({ t, kg, oonp, limitCtx, title, onClose }) {
          const tr = (t.trace || []).filter(p => p && p[0] != null);
          const [hi, setHi] = useState(null);
          const mapRef = useRef(null), mapObj = useRef(null), hover = useRef(null);
          useEffect(() => {
            const L = window.L, el = mapRef.current; if (!L || !el) return;
            const pts = tlmTrack(t); if (pts.length < 2) return;
            const m = L.map(el, { zoomControl: true, attributionControl: true });
            wdSatTiles(L, m);
            // route coloured by height
            const top = Math.max(1, t.maxAltM || 1);
            const col = (h) => { const x = Math.max(0, Math.min(1, (h || 0) / top)); return `hsl(${Math.round(190 - 150 * x)},95%,${Math.round(55 + 5 * x)}%)`; };
            const gp = tr.filter(p => p[3] != null);
            for (let i = 1; i < gp.length; i++) L.polyline([[gp[i - 1][3], gp[i - 1][4]], [gp[i][3], gp[i][4]]], { color: col(gp[i][1]), weight: 4, opacity: 0.95 }).addTo(m);
            const home = t.home || pts[0];
            L.circleMarker(home, { radius: 7, color: '#fff', weight: 2, fillColor: '#16a34a', fillOpacity: 1 }).bindTooltip('Home / take-off').addTo(m);
            L.circleMarker(pts[pts.length - 1], { radius: 6, color: '#fff', weight: 2, fillColor: '#dc2626', fillOpacity: 1 }).bindTooltip('End of log').addTo(m);
            hover.current = L.circleMarker(pts[0], { radius: 7, color: '#0f172a', weight: 2, fillColor: '#facc15', opacity: 0, fillOpacity: 0 }).addTo(m);
            m.fitBounds(L.latLngBounds(pts), { padding: [30, 30], maxZoom: 19 });
            mapObj.current = m;
            setTimeout(() => m.invalidateSize(), 50);
            return () => { m.remove(); mapObj.current = null; };
          }, [t]);
          useEffect(() => {
            const mk = hover.current; if (!mk) return;
            const p = hi != null ? tr[hi] : null;
            if (p && p[3] != null) { mk.setLatLng([p[3], p[4]]); mk.setStyle({ opacity: 1, fillOpacity: 1 }); } else mk.setStyle({ opacity: 0, fillOpacity: 0 });
          }, [hi]);
          useEffect(() => { const k = (e) => { if (e.key === 'Escape') onClose(); }; window.addEventListener('keydown', k); return () => window.removeEventListener('keydown', k); }, []);
          const dur = Math.max(1, t.durationSec || (tr.length ? tr[tr.length - 1][0] : 1));
          const W = 760, L0 = 44, R0 = 44, cw = W - L0 - R0;
          const X = (s) => L0 + (s / dur) * cw;
          const onMove = (e) => {
            const r = e.currentTarget.getBoundingClientRect(); const s = ((e.clientX - r.left) / r.width * W - L0) / cw * dur;
            let best = null, bd = 1e9; tr.forEach((p, i) => { const d = Math.abs(p[0] - s); if (d < bd) { bd = d; best = i; } }); setHi(best);
          };
          // one chart: series = [{ idx, color, label, unit, axis:'l'|'r', fill }]
          const chart = (key, H, series, extra) => {
            const T = 10, B = 18, ch = H - T - B;
            const ax = { l: series.filter(s => s.axis !== 'r'), r: series.filter(s => s.axis === 'r') };
            const rng = (list) => { const v = []; list.forEach(s => tr.forEach(p => { if (p[s.idx] != null) v.push(p[s.idx]); })); if (!v.length) return null; let lo = Math.min(...v), hi2 = Math.max(...v); const fz = list.some(s => s.zero); if (fz) lo = Math.min(0, lo); if (hi2 - lo < 1e-6) hi2 = lo + 1; const pad = (hi2 - lo) * 0.08; return [fz ? lo : lo - pad, hi2 + pad]; };
            const rl = rng(ax.l), rr = rng(ax.r);
            const Y = (v, r) => T + ch - ((v - r[0]) / (r[1] - r[0])) * ch;
            const fmt = (v) => Math.abs(v) >= 100 ? Math.round(v) : Math.round(v * 10) / 10;
            return (
              <svg key={key} viewBox={`0 0 ${W} ${H}`} width="100%" className="block select-none" onMouseMove={onMove} onMouseLeave={() => setHi(null)} data-tlm-chart={key}>
                {rl && [0, 0.5, 1].map(f => { const v = rl[0] + (rl[1] - rl[0]) * f; return <g key={f}><line x1={L0} x2={L0 + cw} y1={Y(v, rl)} y2={Y(v, rl)} stroke="#e2e8f0" strokeWidth="0.7" /><text x={L0 - 4} y={Y(v, rl) + 3} fontSize="9" textAnchor="end" fill={ax.l[0].color}>{fmt(v)}</text></g>; })}
                {rr && [0, 0.5, 1].map(f => { const v = rr[0] + (rr[1] - rr[0]) * f; return <text key={f} x={L0 + cw + 4} y={Y(v, rr) + 3} fontSize="9" fill={ax.r[0].color}>{fmt(v)}</text>; })}
                {extra && extra(Y, rl)}
                {series.map(s => { const r = s.axis === 'r' ? rr : rl; if (!r) return null; const pts = tr.filter(p => p[s.idx] != null).map(p => X(p[0]).toFixed(1) + ',' + Y(p[s.idx], r).toFixed(1));
                  if (pts.length < 2) return null;
                  return <g key={s.label}>{s.fill && <polygon points={`${X(tr[0][0])},${Y(r[0], r)} ${pts.join(' ')} ${X(tr[tr.length - 1][0])},${Y(r[0], r)}`} fill={s.color} fillOpacity="0.15" />}<polyline points={pts.join(' ')} fill="none" stroke={s.color} strokeWidth="1.6" strokeLinejoin="round" /></g>; })}
                {(t.events || []).map((e, i) => <line key={i} x1={X(e.t)} x2={X(e.t)} y1={T} y2={T + ch} stroke="#dc2626" strokeWidth="1" strokeDasharray="3,2" />)}
                {hi != null && tr[hi] && <line x1={X(tr[hi][0])} x2={X(tr[hi][0])} y1={T} y2={T + ch} stroke="#0f172a" strokeWidth="0.8" />}
                <text x={L0} y={H - 4} fontSize="9" fill="#64748b">0:00</text>
                <text x={L0 + cw} y={H - 4} fontSize="9" textAnchor="end" fill="#64748b">{fmtMmSs(dur)}</text>
                <text x={L0 + cw / 2} y={H - 4} fontSize="9" textAnchor="middle">{series.map((s, i) => <tspan key={i} fill={s.color}>{i ? '   ' : ''}— {s.label}{s.unit ? ' (' + s.unit + ')' : ''}</tspan>)}</text>
              </svg>
            );
          };
          const has = (i) => tr.some(p => p[i] != null);
          const p = hi != null ? tr[hi] : null;
          const ke = telemetryKe(t, kg);
          const box = (label, value, sub, warn) => (
            <div className="bg-white border border-slate-200 rounded-lg px-3 py-2"><div className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{label}</div><div className={`text-base font-bold font-mono ${warn ? 'text-red-600' : 'text-slate-800'}`}>{value}</div>{sub && <div className="text-[10px] text-slate-500">{sub}</div>}</div>
          );
          const ft = (m) => Math.round(m * 3.28084);
          return (
            <div className="fixed inset-0 z-[4500] bg-slate-900/70 flex items-center justify-center p-2 sm:p-4 print:hidden" data-testid="tlm-detail" onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}>
              <div className="bg-slate-50 rounded-xl shadow-2xl w-full max-w-6xl max-h-[96vh] flex flex-col overflow-hidden">
                <div className="px-5 py-3 bg-white border-b border-slate-200 flex items-center gap-3">
                  <i className="fa-solid fa-satellite-dish text-cyan-600"></i>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-semibold text-slate-800 truncate">{title || 'Flight'} · {fmtTlmDate(t.startMs)} {fmtTlmTime(t.startMs)}–{fmtTlmTime(t.endMs)}</h3>
                    <p className="text-xs text-slate-500 truncate">{fmtMmSs(t.durationSec)} armed · radio clock {t.clock === 'local' ? 'local' : 'UTC'}{t.file ? ' · ' + t.file : ''}</p>
                  </div>
                  <button onClick={onClose} data-tlm-close="1" className="text-slate-400 hover:text-slate-700 text-xl px-2" title="Close (Esc)"><i className="fa-solid fa-xmark"></i></button>
                </div>
                <div className="overflow-auto p-4 space-y-3">
                  <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-2">
                    {box('Max height', t.maxAltM != null ? t.maxAltM + ' m' : '—', t.maxAltM != null ? ft(t.maxAltM) + ' ft above ' + (t.altRef === 'landing' ? 'landing' : t.altRef === 'lowest' ? 'lowest point' : 'take-off') : '', t.maxAltM > 120)}
                    {box('Max speed', t.maxSpeedKmh != null ? t.maxSpeedKmh + ' km/h' : '—', 'GPS ground speed')}
                    {box('Max distance', t.maxDistM != null ? t.maxDistM + ' m' : '—', 'from home')}
                    {box('Path flown', t.pathM ? (t.pathM / 1000).toFixed(2) + ' km' : '—', '')}
                    {box('Battery', t.vStart != null ? t.vStart + '→' + t.vEnd + ' V' : '—', [t.cells ? t.cells + 'S' : '', t.vMin != null ? 'sag ' + t.vMin + ' V' : ''].filter(Boolean).join(' · '))}
                    {box('Used', t.mahUsed != null ? t.mahUsed + ' mAh' : '—', t.maxCurrA != null ? 'max ' + t.maxCurrA + ' A · avg ' + t.avgCurrA + ' A' : '')}
                    {box('Link', t.minRq != null ? 'RQ ' + t.minRq + '%' : '—', [t.minRss != null ? 'min ' + t.minRss + ' dBm' : '', t.maxTpwr != null ? t.maxTpwr + ' mW' : ''].filter(Boolean).join(' · '), t.minRq != null && t.minRq < 50)}
                    {box('Peak KE', ke != null ? ke.toFixed(1) + ' J' : '—', ke != null ? Math.round(t.keAt.v * 3.6) + ' km/h at ' + t.keAt.h + ' m · ' + kg + ' kg' : 'add weight in the fleet', oonp === true && ke > 34)}
                  </div>
                  <div className="grid grid-cols-1 lg:grid-cols-5 gap-3">
                    <div className="lg:col-span-3 bg-white border border-slate-200 rounded-lg overflow-hidden relative">
                      <div ref={mapRef} data-tlm-map="1" className="w-full h-[340px] lg:h-[430px] bg-slate-200" style={{ zIndex: 0 }}></div>
                      {tlmTrack(t).length < 2 && <div className="absolute inset-0 flex items-center justify-center text-sm text-slate-500">No GPS track in this log.</div>}
                      <div className="absolute bottom-1 left-1 z-[400] bg-white/90 rounded px-2 py-1 text-[10px] text-slate-700 flex items-center gap-2">
                        <span className="inline-block w-2.5 h-2.5 rounded-full bg-green-600"></span>Home
                        <span className="inline-block w-2.5 h-2.5 rounded-full bg-red-600 ml-1"></span>End
                        <span className="ml-1">Route colour: </span><span className="inline-block w-16 h-2 rounded" style={{ background: 'linear-gradient(90deg,hsl(190,95%,55%),hsl(115,95%,57%),hsl(40,95%,60%))' }}></span><span>low → high</span>
                      </div>
                    </div>
                    <div className="lg:col-span-2 bg-white border border-slate-200 rounded-lg p-3 text-xs text-slate-700 space-y-1">
                      <div className="font-semibold text-slate-800 mb-1">{p ? 'At ' + fmtMmSs(p[0]) : 'Hover a chart to follow the flight on the map'}</div>
                      {p && <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 font-mono" data-tlm-readout="1">
                        <span className="text-slate-500">Height</span><span>{p[1] != null ? p[1] + ' m (' + ft(p[1]) + ' ft)' : '—'}</span>
                        <span className="text-slate-500">Speed</span><span>{p[2] != null ? p[2] + ' km/h' : '—'}</span>
                        <span className="text-slate-500">Battery</span><span>{p[5] != null ? p[5] + ' V' + (t.cells ? ' (' + (p[5] / t.cells).toFixed(2) + ' V/cell)' : '') : '—'}</span>
                        <span className="text-slate-500">Current</span><span>{p[6] != null ? p[6] + ' A' : '—'}</span>
                        <span className="text-slate-500">Link RQ</span><span>{p[7] != null ? p[7] + '%' : '—'}</span>
                        <span className="text-slate-500">GPS sats</span><span>{p[8] != null ? p[8] : '—'}</span>
                        <span className="text-slate-500">Position</span><span>{p[3] != null ? p[3].toFixed(5) + ', ' + p[4].toFixed(5) : '—'}</span>
                      </div>}
                      <div className="border-t border-slate-100 pt-2 mt-2 space-y-0.5">
                        {flightLimitIssues(t, { ...(limitCtx || {}), kg, oonp }).map((x, i) => <div key={'l' + i} className={x.sev === 'red' ? 'text-red-700 font-semibold' : 'text-amber-700 font-semibold'}>⚠ {x.text}</div>)}
                        {(t.events || []).map((e, i) => <div key={i} className="text-red-700 font-semibold">⚠ {fmtMmSs(e.t)}: {e.text}</div>)}
                        {(t.notes || []).map((n, i) => <div key={'n' + i} className="text-amber-700">ⓘ {n}</div>)}
                        {t.minSats != null && <div>GPS sats {t.minSats}–{t.maxSats}{t.home ? ` · home ${t.home[0].toFixed(5)}, ${t.home[1].toFixed(5)}` : ''}</div>}
                        <div className="text-slate-500">{t.altRef === 'landing' ? 'Height is measured from the landing point (smoothed telemetry altitude).' : t.altRef === 'lowest' ? 'Height is measured from the lowest point of the flight (no time on the ground in this log).' : 'Height is measured from ground level at take-off (smoothed telemetry altitude; GPS-based heights are typically ±5 m).'}</div>
                      </div>
                    </div>
                  </div>
                  <div className="bg-white border border-slate-200 rounded-lg p-2 space-y-1">
                    {chart('alt', 190, [{ idx: 1, color: '#1d76d2', label: 'height', unit: 'm', fill: true, zero: true }, { idx: 2, color: '#d97706', label: 'speed', unit: 'km/h', axis: 'r', zero: true }],
                      (Y, r) => r && r[1] >= 120 ? <line x1={L0} x2={L0 + cw} y1={Y(120, r)} y2={Y(120, r)} stroke="#dc2626" strokeWidth="0.8" strokeDasharray="4,3" /> : null)}
                    {(has(5) || has(6)) && chart('bat', 150, [...(has(5) ? [{ idx: 5, color: '#7c3aed', label: 'battery', unit: 'V' }] : []), ...(has(6) ? [{ idx: 6, color: '#db2777', label: 'current', unit: 'A', axis: 'r', zero: true }] : [])])}
                    {(has(7) || has(8)) && chart('link', 130, [...(has(7) ? [{ idx: 7, color: '#059669', label: 'link quality', unit: '%', zero: true }] : []), ...(has(8) ? [{ idx: 8, color: '#64748b', label: 'GPS sats', axis: 'r', zero: true }] : [])])}
                    {!has(5) && <div className="text-[11px] text-slate-400 px-2">Battery, current and link charts appear for logs imported with v5.41 or later.</div>}
                  </div>
                </div>
              </div>
            </div>
          );
        }

