          // Resolve items for a section: db override → default
          const getOonpItems = (key) => {
            const saved = db.oonpChecklists && db.oonpChecklists[key];
            if (!saved) return DEFAULT_OONP_CHECKLISTS[key] || [];
            // v5.46: a checklist customised earlier still gets the RF coordination item
            if (key === 'preflight' && !saved.some(i => i.id === 'rfCoordinated') && !(db.oonpRemovedDefaults || []).includes('rfCoordinated')) return [...saved, DEFAULT_OONP_CHECKLISTS.preflight.find(i => i.id === 'rfCoordinated')];
            return saved;
          };

          // Save updated items to db
          const saveOonpItems = (key, items) =>
            setDb(prev => {
              const updated = { ...(prev.oonpChecklists || {}), [key]: items };
              const removed = key === 'preflight' && !items.some(i => i.id === 'rfCoordinated') ? [...new Set([...(prev.oonpRemovedDefaults || []), 'rfCoordinated'])] : (prev.oonpRemovedDefaults || []).filter(x => !(key === 'preflight' && x === 'rfCoordinated' && items.some(i => i.id === x)));
              return { ...prev, oonpChecklists: updated, oonpRemovedDefaults: removed };
            });

