              +'else if(z.type==="rect")ly=L.rectangle([z.geo.a,z.geo.b],zs);else if(z.type==="polygon")ly=L.polygon(z.geo.pts,zs);'
              +'if(ly){ly.addTo(hm);ly.bindTooltip("EXCLUSION ZONE",{permanent:true,direction:"center",className:"hzt"});}});}'
              +'setTimeout(go,10000);'
              +'}';

            // ── Assemble ──────────────────────────────────────────────────────
            const P=[];
            P.push('<!DOCTYPE html><html><head><meta charset="UTF-8"/>');
            // The browser uses this title as the saved PDF's file name: "<operation> dd.mm.yy" (range for multi-day events) (v5.52)
            { const w=opWindow(ov), dmy=(iso)=>{const m=String(iso||'').match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'.'+m[2]+'.'+m[1].slice(2):'';};
              const dt=dmy(w.sd)+(w.ed&&w.ed!==w.sd&&dmy(w.ed)?'-'+dmy(w.ed):'');
              const nm=String(ov.operationName||ov.identifier||'Flight Record').replace(/[\\/:*?"<>|]+/g,'-').replace(/\s+/g,' ').trim();
              P.push('<title>'+esc(nm+(dt?' '+dt:''))+'</title>'); }
            { const lc = document.getElementById('wd-leaflet-css'); P.push(lc ? '<style>' + lc.textContent + '</style>' : '<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.css"/>'); }
            const cssq=(t)=>'"'+String(t||'').replace(/["\\\n\r]/g,' ')+'"';
            P.push('<style>@page{size:A4 portrait;margin:20mm 14mm 16mm 14mm;'
              +'@bottom-left{content:'+cssq((ov.identifier||'')+' · '+(ov.operationName||'Flight Record')+' · '+(co.name||''))+';font:7pt Arial,sans-serif;color:#94a3b8;}'
              +'@bottom-right{content:"Page " counter(page) " of " counter(pages);font:7pt Arial,sans-serif;color:#94a3b8;}}@media print{.pdfhdr{margin:0 0 14pt!important;border-radius:4pt;}}'
              +'*{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;}'
              +'body{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:'+S8+';margin:0;background:white;}'
              +'table{border-collapse:collapse;width:100%;}td,th{vertical-align:top;}'
              +'.hzt{background:transparent!important;border:none!important;box-shadow:none!important;color:#fff;font-weight:800;font-size:7pt;text-shadow:0 0 2px #000;}.hzt:before{display:none;}'
              +'.leaflet-tooltip{background:transparent!important;border:none!important;box-shadow:none!important;padding:0!important;}'
              +'@media screen{body{max-width:210mm;margin:0 auto;padding:20mm 14mm;box-shadow:0 0 20px rgba(0,0,0,.1);}}'
                            +'</style>');
            { const lj = document.getElementById('wd-leaflet-js'); P.push(lj ? '<scri'+'pt>' + lj.textContent + '<'+'/scri'+'pt>' : '<scri'+'pt src="https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.min.js"><'+'/scri'+'pt>'); }
            P.push('<scri'+'pt>'+mapInitFn+'<'+'/scri'+'pt>');
            P.push('</head>');
            P.push('<body onload="initMap()">');
            

            // Header
            P.push('<div class="pdfhdr" style="background:'+PU+';color:white;padding:10pt 14pt;margin:-20mm -14mm 14pt;display:flex;justify-content:space-between;align-items:flex-start;">');
            P.push('<div><div style="font-size:13pt;font-weight:800;">'+esc(val(co.name||'Waking Dream FPV'))+'</div>'
              +'<div style="font-size:7pt;opacity:.7;margin-top:2pt;">RPAS Operations Planner · ReOC: '+esc(val(co.reocNumber))+' · ARN: '+esc(val(co.companyArn))+' · '+esc(val(co.email))+'</div></div>');
            P.push('<div style="text-align:right;"><div style="font-size:10pt;font-weight:700;">'+esc(val(ov.identifier))+'</div>'
              +'<div style="font-size:7pt;opacity:.7;">'+esc(fmtD(ov.operationDate))+(ov.operationEndDate?' – '+esc(fmtD(ov.operationEndDate)):'')+'</div></div></div>');

            // Title
            P.push('<div style="border-bottom:3px solid '+PU+';padding-bottom:8pt;margin-bottom:12pt;">');
            P.push('<div style="font-size:15pt;font-weight:800;color:'+NV+';">'+esc(val(ov.operationName||ov.identifier))+'</div>');
            P.push('<div style="display:flex;gap:16pt;margin-top:6pt;flex-wrap:wrap;">');
            [{l:'Client',v:ov.clientName},{l:'RPIC',v:ov.rpic},{l:'Start',v:fmtD(ov.operationDate)+' '+(ov.startTime||'')},
             {l:'End',v:fmtD(ov.operationEndDate||ov.operationDate)+' '+(ov.endTime||'')},{l:'Assessor',v:ov.assessor},
             {l:'Status',v:approval.flightAuthApproved?'✓ AUTHORISED':'⚠ PENDING',c:approval.flightAuthApproved?'#16a34a':'#dc2626'}]
            .forEach(function(x){P.push('<span><div style="font-size:6.5pt;color:'+S6+';font-weight:700;text-transform:uppercase;">'+esc(x.l)+'</div><div style="font-size:8.5pt;font-weight:700;'+(x.c?'color:'+x.c+';':'')+'">'+esc(val(x.v))+'</div></span>');});
