          const handleSaveApprovedPlan = async () => {
            if (!approval.flightAuthApproved) {
              alert('Flight Authorisation must be approved before saving the plan.');
              return;
            }
            const ov = resolvePlanId(); if (!ov) return;
            const title = getOpTitle(ov);
            const plan = {
              id: ov.identifier, title,
              savedAt: new Date().toISOString(), status: 'approved',
              ...buildPlanSnapshot(ov),
            };
            const newDb = { ...db,
              savedPlans: [plan, ...(db.savedPlans || []).filter(p => p.id !== plan.id)],
              draftPlans: (db.draftPlans || []).filter(p => p.id !== plan.id) };
            if (!(await persistDbNow(newDb))) return;
            setDb(newDb);
            { const problem = await verifySaved('savedPlans', plan); if (problem) { alert(`⚠ Plan saved, but the check after saving failed: ${problem}.\n\nExport a backup from Database & Settings before closing.`); return; } }
            markSaved();
            alert(`Plan saved: "${title}"\n\nReturn to it from the Database & Settings tab.`);
          };

          // Start a new job from an existing plan: keeps the site, map, risks, OONP set-up and crew;
          // clears everything that belongs to one particular day.
          const handleCopyPlan = (p) => {
            const srcOv = p.overview || {};
            const d0 = cParse(srcOv.operationDate), d1 = cParse(srcOv.operationEndDate);
            const span = d0 && d1 && d1 > d0 ? cDiff(d1, d0) : 0;
            const ans = window.prompt(`Start a new job from "${p.title}"?\n\nCopied: site, map and pins, risk register, JSA, OONP set-up, KE charts, crew, client, photos.\nCleared: dates, approval and signatures, NOTAMs, post-flight log and telemetry, consent answers, amendments.\nIt gets a new operation ID.\n\nDate of the new job (YYYY-MM-DD):`, localISODate());
            if (ans === null) return;
            const date = /^\d{4}-\d{2}-\d{2}$/.test(ans.trim()) && cParse(ans.trim()) ? ans.trim() : localISODate();
            const c = JSON.parse(JSON.stringify(p));
            const newId = nextOpId(db);
            c.overview = { ...srcOv, identifier: newId, uid: newUid(), operationDate: date, operationEndDate: span ? localISODate(cAddDays(cParse(date), span)) : '' };
            const pa = c.approval || {};
            // standing references (e.g. CASA.RPAS.1040, restrictions) carry over; everything that is signed per job does not
            c.approval = { ...getInitialApproval(), otherRestrictions: pa.otherRestrictions || '', officialAuth: pa.officialAuth || '' };
            c.log = getInitialLog();
            c.oonp = { ...(c.oonp || {}), checkboxes: {} };
            c.amendments = [];
            c.title = getOpTitle(c.overview);
            if (!window.confirm(`This replaces the current form with a new job ${newId} (${c.title}). Anything unsaved in the form will be lost.\n\nContinue?`)) return;
            handleLoadPlan(c, { silent: true });
            autoIdRef.current = null;
            setTimeout(() => alert(`New job ${newId} started from "${p.title}".\n\nIt isn't saved yet. Check the details, risks and NOTAMs for the new date, then Save Draft.`), 450);
          };

          const handleLoadPlan = (plan, opts = {}) => {
            if (!opts.silent && plan.status !== 'draft') {
              const newer = (db.draftPlans || []).find(p => p.id === plan.id && Date.parse(p.savedAt || 0) > Date.parse(plan.savedAt || 0));
              if (newer && window.confirm(`There is a NEWER DRAFT of this job (saved ${new Date(newer.savedAt).toLocaleString('en-AU')}).\n\nOK: open the newer draft\nCancel: open this ${plan.status || 'saved'} copy`)) { plan = newer; }
            }
            if (!opts.silent && dirty && !window.confirm(`You have unsaved changes to the job that's open now. Loading "${plan.title}" will discard them.\n\nContinue?`)) return;
            if (!opts.silent && !dirty && !window.confirm(`Load "${plan.title}"? This will replace the current form.`)) return;
            quietUntilRef.current = Date.now() + 2500; setDirty(false);
            planLoadingRef.current = true;
            const clone = (o) => (o === undefined || o === null) ? o : JSON.parse(JSON.stringify(o));
            const emptyMap = { launches: [], recoveries: [], signage: [], areaPolygon: [], crowdZones: [], exclusionZones: [] };
            const md = { ...emptyMap, ...(clone(plan.mapData) || {}) };
            setOverview(plan.overview ? { ...getInitialOverview(), ...clone(plan.overview) } : getInitialOverview());
            setChecklist(plan.checklist ? clone(plan.checklist) : getInitialChecklist());
            setChecklistNotes(plan.checklistNotes ? clone(plan.checklistNotes) : getInitialChecklistNotes());
            setJsa(plan.jsa ? { ...getInitialJsa(), ...clone(plan.jsa) } : getInitialJsa());
            setRisks(plan.risks ? clone(plan.risks) : []);
            setApproval(plan.approval ? { ...getInitialApproval(), ...clone(plan.approval) } : getInitialApproval());
            setOonp({ ...getInitialOonp(), ...(clone(plan.oonp) || {}) });
            setOonpMode(plan.oonpMode !== undefined ? !!plan.oonpMode : false);
            if (Array.isArray(plan.oonpSections)) setOonpSections([...plan.oonpSections]);
            setLog(plan.log ? { ...getInitialLog(), ...clone(plan.log) } : getInitialLog());
            setMapData(md);
            setSiteAttachments(clone(plan.siteAttachments) || []);
            setBallistic(plan.ballistic ? clone(plan.ballistic) : { enabled: false, height: 5.0, speed: 5.0 });
            setKeData(plan.keData ? { enabled: false, rpa: '', weight: 0, useAero: false, rho: 1.225, cd: 1.2, area: 0.05, ...clone(plan.keData) }
                                  : { enabled: false, rpa: '', weight: 0, useAero: false, rho: 1.225, cd: 1.2, area: 0.05 });
            setExtraKe(clone(plan.extraKe) || []);
            if (plan.keModel) setKeModel(plan.keModel);
            setHeatExclZones(clone(plan.heatExclZones) || []);
            setHeatStrokes(clone(plan.heatStrokes) || []);
            amendmentsRef.current = clone(plan.amendments) || [];
            setActiveTab('preliminary');

            // Put the map back over the saved layout, then re-project every pin from its GPS
            setTimeout(() => {
              const m = leafletMapRef.current;
              if (m) {
                m.invalidateSize();
                const pts = [];
                (md.areaPolygon || []).forEach(p => { if (p.lat != null) pts.push([p.lat, p.lng]); });
                ['launches', 'recoveries', 'signage'].forEach(k => (md[k] || []).forEach(p => { if (p.lat != null) pts.push([p.lat, p.lng]); }));
                if (pts.length > 1) m.fitBounds(window.L.latLngBounds(pts).pad(0.25), { animate: false, maxZoom: 19 });
                else if (pts.length === 1) m.setView(pts[0], Math.max(m.getZoom(), 17), { animate: false });
                else if (plan.overview?.location) { const c = extractBaseCoords(plan.overview.location); m.setView([c.lat, c.lng], m.getZoom(), { animate: false }); }
              }
              setTimeout(() => { reprojectMapData(); planLoadingRef.current = false; }, 300);
            }, 150);

            // Tell the user exactly what came back (and what this plan never contained)
            const n = (a) => (a || []).length;
            const lines = [];
            lines.push(`Map: ${n(md.areaPolygon) > 2 ? 'ops area' : 'no ops area'}, ${n(md.launches)} launch, ${n(md.recoveries)} recovery, ${n(md.signage)} signage, ${n(md.exclusionZones)} exclusion zone(s)`);
            const keCount = (plan.keData && plan.keData.enabled ? 1 : 0) + n(plan.extraKe);
            lines.push(`KE charts: ${keCount}${plan.keData && plan.keData.rpa ? ' (' + [plan.keData.rpa, ...(plan.extraKe || []).map(k => k.rpa)].filter(Boolean).join(', ') + ')' : ''}`);
            lines.push(`Ballistic visualiser: ${plan.ballistic && plan.ballistic.enabled ? 'on' : 'off'} · Heatmap: ${n(plan.heatStrokes) ? 'painted' : 'none'}`);
            { const o = plan.oonp || {}, eq = ['videoTx', 'videoFreq', 'rcLink', 'rcFreq', 'mediaFormat'].map(k => o[k]).filter(Boolean);
              const ppl = ['venueContact', 'callTime', 'rfCoordinator', 'pyroCoordinator', 'mediaLead'].filter(k => o[k]).length;
              lines.push(`OONP: ${plan.oonpMode ? 'on' : 'off'} · equipment ${eq.length ? eq.join(' / ') : 'none saved'} · ${ppl} logistics field${ppl === 1 ? '' : 's'} · ${Object.keys(o.checkboxes || {}).length} checklist answers`); }
            const missing = ['mapData', 'keData', 'extraKe', 'ballistic'].filter(k => plan[k] === undefined);
            if (missing.length) lines.push(`\n⚠ This plan was saved by an older version that didn't store: ${missing.join(', ')}.\nRe-enter those parts and save again — they will be kept from now on.`);
            if (!opts.silent) setTimeout(() => alert(`Loaded "${plan.title}"\n\n` + lines.join('\n')), 400);
          };

